//! The text of one generated file: head, tables, functions and helpers.
//!
//! Pattern: Template — the file is assembled from the pieces the other emitters write; one root interface gives
//! the top level, several roots give one module each.

use std::collections::BTreeSet;
use std::fmt::Write;

use super::command::{GENERATED_BY, GeneratedFile};
use super::ctx::{Ctx, MarkSource, Work};
use super::text::Text;
use super::{listener, readers, runfn, setters, table};
use crate::model::{Model, RequestedFile};
use crate::rt::ABI;
use crate::tree::{Tree, roots};

/// The files of a model, one `<stem>_cli.rs` for every requested file that has commands. A file with one root
/// interface has its table and functions at the top; with several, each root gets a module named like it.
///
/// # Errors
/// A method collides with a reserved word, or two commands get the same words.
pub fn generate(m: &Model, marks: &dyn MarkSource) -> capnp::Result<Vec<GeneratedFile>> {
    let mut files = Vec::new();
    for f in &m.files {
        let rs = roots(m, &f.stem);
        if rs.is_empty() {
            continue;
        }
        let mut bodies = Vec::new();
        for id in &rs {
            bodies.push((*id, body(m, marks, &Tree::build(m, *id)?)));
        }
        let rpc = bodies.iter().any(|b| b.1.1);
        let mut w = Text::default();
        head(&mut w, f, rpc);
        let mut content = w.finish();
        if let [(_, (text, _))] = bodies.as_slice() {
            content.push('\n');
            content.push_str(text);
        } else {
            for (id, (text, _)) in &bodies {
                let name = crate::model::module_name(&m.interfaces[id].name.replace('.', "_"));
                let _ = write!(
                    content,
                    "\npub mod {name} {{\n    #[allow(unused_imports)]\n    use capnpc_cli::rt::{{CallError, Command, ErrorKind, Group, Held, Input, Output, Param, ParamTy, Sink, Value, join}};\n{text}}}\n"
                );
            }
        }
        files.push(GeneratedFile {
            name: format!("{}_cli.rs", f.stem),
            content,
        });
    }
    Ok(files)
}

/// The tables, functions and helpers of one tree, and whether it has listener servers.
fn body(m: &Model, marks: &dyn MarkSource, t: &Tree) -> (String, bool) {
    let mut ctx = Ctx::new(m, marks);
    let root_client = format!("{}::Client", m.path(t.root));
    let mut runs = Text::default();
    for c in &t.commands {
        runs.blank();
        runfn::run_fn(&mut ctx, &mut runs, c, &root_client);
    }
    let mut listeners = BTreeSet::new();
    for c in t.commands.iter().filter(|c| c.watch) {
        listeners.extend(table::listener_fields(m, c).into_iter().map(|(_, id)| id));
    }
    let mut lines = Text::default();
    for id in &listeners {
        lines.blank();
        listener::emit(&mut ctx, &mut lines, *id);
    }
    while let Some(w) = ctx.next() {
        let (kind, name, text) = match w {
            Work::Setter(id) => (0, ctx.ident("set", id), setters::set_fn(&mut ctx, id)),
            Work::Out(id) => (1, ctx.ident("out", id), readers::out_fn(&mut ctx, id)),
            Work::Enum(id) => (2, ctx.ident("enum", id), readers::enum_fn(&ctx, id)),
        };
        ctx.pieces.insert((kind, name), text);
    }
    let mut w = Text::default();
    table::emit(&ctx, &mut w, t, &root_client);
    let mut out = w.finish();
    out.push_str(&runs.finish());
    out.push_str(&lines.finish());
    for text in ctx.pieces.values() {
        out.push('\n');
        out.push_str(text);
    }
    (out, !listeners.is_empty())
}

fn head(w: &mut Text, file: &RequestedFile, rpc: bool) {
    w.line(format!(
        "// @generated by {GENERATED_BY} (rt ABI {ABI}) from {}; do not edit by hand.",
        file.name
    ));
    w.line("// The calls go through the typed clients capnpc-rust wrote for the same request.");
    if rpc {
        w.line("// This file has listener servers: the crate needs `capnp-rpc` as well.");
    }
    w.blank();
    w.line("#[allow(unused_imports)]");
    w.line("use capnpc_cli::rt::{CallError, Command, ErrorKind, Group, Held, Input, Output, Param, ParamTy, Sink, Value, join};");
    w.blank();
    w.line(format!("pub const GENERATED_BY: &str = {GENERATED_BY:?};"));
    w.line(format!("pub const RT_ABI: u32 = {ABI};"));
    w.line("const _: () = assert!(RT_ABI == capnpc_cli::rt::ABI);");
}
